// step-closure.mjs: the build-order contract behind check-index's step-import-closure and
// step-manifest rules. A build step may say what it copies ({ skill, paths }), installs
// ({ package, companions }) and generates ({ tool, paths, installs? }). This module finds each copied file's
// template by the repo path on its first line (or its path under templates/) in the named skill's
// templates/ or examples/, then plays the order step by step and proves that every relative and
// aliased import (@/..., @test/...) resolves to a file copied or generated by then, that every npm
// import is installed by then, that every copied file brings its sibling test in the same step, and
// that no runtime file waits for a later step's test (test:coverage would drop in between).
// Not an entry point.

import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { builtinModules } from 'node:module';
import { join, posix, relative } from 'node:path';

import { globToRegExp, maskComments, toPosix } from '../check-lib.mjs';

/** The single-app layout (DECISIONS section 3): @/* -> src/*, @test/* -> test/*. */
export const CLOSURE_DEFAULTS = Object.freeze({
  aliases: [{ prefix: '@/', to: 'src/' }, { prefix: '@test/', to: 'test/' }],
  roots: ['src', 'test', '__mocks__', 'scripts', 'contracts', '.maestro', '.github', 'design', 'assets'],
  coverage: ['src/**'],
  placeholders: {},
});

const CODE = /\.(ts|tsx|js|mjs|cjs)$/;
const TEST = /\.(test|golden\.test|sim\.test|perf\.test)\.(ts|tsx)$/;
const PLACEHOLDER = /__[A-Z][A-Z0-9_]*__/;
const ROOT_FILE = /^(package\.json|tsconfig[\w.]*\.json|[\w.-]+\.config\.(?:js|cjs|mjs|ts|json)|knip\.json|quality-gates\.json|lefthook\.yml|eas\.json|index\.ts|\.[\w.-]+)$/;
const BUILTINS = new Set(builtinModules.flatMap((name) => [name, `node:${name}`]));
const RUNTIME_EXPORT = /^export\s+(?:async\s+)?function\b|^export\s+(?:abstract\s+)?class\b|^export\s+const\s+\w+\s*(?::[^=\n]+)?=\s*(?:async\s*)?(?:<[^>]*>\s*)?(?:\([^)]*\)|\w+)\s*(?::[^=\n]+)?=>|^export\s+const\s+\w+\s*=\s*(?:async\s+)?function\b|^export\s+const\s+\w+\s*(?::[^=\n]+)?=\s*[A-Za-z_$][\w$]*\s*(?:<[^>]*>)?\(/m;

/** The closure settings: the index data's `closure` block over the defaults. */
export function closureConfig(closure = {}) {
  const config = { ...CLOSURE_DEFAULTS, ...closure };
  const roots = config.roots.map((root) => root.replace(/\/$/, '').replace(/[.]/g, '\\.'));
  return {
    ...config,
    lineOne: new RegExp(`^\\s*(?:\\/\\/|#|\\/\\*|<!--)\\s*((?:${roots.join('|')})\\/[^\\s*:]+|[A-Za-z_.][\\w.-]*\\.(?:js|cjs|mjs|ts|tsx|json|yml|yaml))(?=[\\s:]|\\*\\/|-->|$)`),
    rootPrefix: new RegExp(`^(?:${roots.join('|')})\\/`),
    fill: (value) => Object.entries(config.placeholders).reduce((out, [token, filled]) => out.replaceAll(token, filled), value),
  };
}

function walkFiles(dir, out = []) {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const entry of entries) {
    if (entry.name === 'node_modules' || entry.name === '.DS_Store') continue;
    const path = join(dir, entry.name);
    if (entry.isDirectory()) walkFiles(path, out);
    else if (entry.isFile()) out.push(path);
  }
  return out;
}

function readText(file) {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return '';
  }
}

/**
 * The repo path a template stands for: its line-1 comment (`// src/core/result.ts`), else its path
 * under templates/ when that already is a repo path (templates/src/..., templates/dot-prettierrc.json
 * becomes .prettierrc.json). Returns null for prose, samples and anything else that is not copied.
 */
export function templateRepoPath(skillDir, file, config) {
  const rel = toPosix(relative(skillDir, file));
  const first = readText(file).slice(0, 400).split('\n')[0];
  const named = config.lineOne.exec(first);
  if (named && (config.rootPrefix.test(named[1]) || ROOT_FILE.test(named[1]))) return named[1];
  if (!rel.startsWith('templates/')) return null;
  const under = rel.slice('templates/'.length).replace(/(^|\/)dot-([^/]+)$/, '$1.$2');
  if (config.rootPrefix.test(under)) return under;
  if (!under.includes('/') && ROOT_FILE.test(under)) return under;
  return null;
}

/**
 * skill -> Map(repo path -> { file, raw, placeholder, example }), from templates/ and examples/ (tests/
 * is never read; templates/ wins when both name a path). A template whose path keeps an unfilled
 * __PLACEHOLDER__ stands for its filled path only when a copy glob names a placeholder too; a literal
 * path always wins over it. An example is a shape to imitate, never copied: only a literal path, or a
 * copy that says examples: true, takes one.
 */
export function indexTemplates(skillsRoot, skillNames, config) {
  const bySkill = new Map();
  for (const skill of skillNames) {
    const dir = join(skillsRoot, skill);
    const map = new Map();
    for (const sub of ['templates', 'examples']) {
      for (const file of walkFiles(join(dir, sub)).sort()) {
        const raw = templateRepoPath(dir, file, config);
        if (!raw) continue;
        const placeholder = PLACEHOLDER.test(raw);
        const path = config.fill(raw);
        const taken = map.get(path);
        if (!taken || (taken.placeholder && !placeholder)) map.set(path, { file, raw, placeholder, example: sub === 'examples' });
      }
    }
    bySkill.set(skill, map);
  }
  return bySkill;
}

/** The [start, end) spans of every string and template literal in comment-free code. */
function stringSpans(code) {
  const spans = [];
  let i = 0;
  while (i < code.length) {
    const ch = code[i];
    if (ch === '"' || ch === "'" || ch === '`') {
      let j = i + 1;
      while (j < code.length && code[j] !== ch) {
        if (code[j] === '\\') j += 1;
        else if (ch !== '`' && code[j] === '\n') break;
        j += 1;
      }
      spans.push([i, j + 1]);
      i = j + 1;
      continue;
    }
    i += 1;
  }
  return spans;
}

/**
 * Every module specifier a JS/TS file imports: static imports and re-exports (a statement that starts
 * a line), side-effect imports, dynamic import() and require(). Text inside a string or template
 * literal (generated code, test fixtures) is not an import.
 */
export function importsOf(text, config) {
  const code = maskComments(config ? config.fill(text) : text);
  const spans = stringSpans(code);
  const inString = (index) => spans.some(([from, to]) => index > from && index < to);
  const found = [];
  const patterns = [
    /^[ \t]*(?:import|export)\s+(?:type\s+)?[^'";]*?\bfrom\s*(['"])([^'"\n]+)\1/gm,
    /^[ \t]*import\s*(['"])([^'"\n]+)\1/gm,
    /\bimport\(\s*(['"])([^'"\n]+)\1\s*\)/g,
    /\brequire\(\s*(['"])([^'"\n]+)\1\s*\)/g,
  ];
  for (const re of patterns) {
    for (const match of code.matchAll(re)) {
      const keyword = match.index + match[0].search(/\S/);
      if (!inString(keyword)) found.push(match[2]);
    }
  }
  return [...new Set(found)];
}

/** The npm package of a bare specifier ('@scope/name/sub' -> '@scope/name'), or null for paths and built-ins. */
export function packageOf(specifier) {
  if (specifier.startsWith('.') || specifier.startsWith('/') || specifier.startsWith('node:') || BUILTINS.has(specifier) || BUILTINS.has(specifier.split('/')[0])) return null;
  const parts = specifier.split('/');
  return specifier.startsWith('@') ? parts.slice(0, 2).join('/') : parts[0];
}

/** The repo path an import names, for relative and aliased imports; null for npm packages. */
export function resolveImport(fromRepoPath, specifier, config) {
  if (specifier.startsWith('.')) return posix.normalize(posix.join(posix.dirname(fromRepoPath), specifier));
  const alias = [...config.aliases].sort((a, b) => b.prefix.length - a.prefix.length).find((entry) => specifier.startsWith(entry.prefix));
  return alias ? `${alias.to}${specifier.slice(alias.prefix.length)}` : null;
}

/** The present file an import resolves to, trying the extension-less forms the bundler accepts. */
function presentTarget(target, isPresent) {
  const candidates = /\.[a-z0-9]+$/i.test(target) ? [target] : [];
  candidates.push(`${target}.ts`, `${target}.tsx`, `${target}/index.ts`, `${target}/index.tsx`);
  return candidates.find(isPresent) ?? null;
}

function makeGlob(config) {
  const cache = new Map();
  return (path, glob) => {
    if (!cache.has(glob)) cache.set(glob, globToRegExp(config.fill(glob).replace(/\/$/, '/**')));
    return cache.get(glob).test(path);
  };
}

/** The positions of an order's steps: { key, label, number, copies, installs, generates, skills }. */
function orderSteps(steps, prefix) {
  return steps.map((step, index) => ({ key: `${prefix}${index + 1}`, label: `step ${index + 1}`, number: index + 1, copies: step.copies ?? [], installs: step.installs ?? [], generates: step.generates ?? [], skills: step.skills }));
}

/** True when the data describes copies for an order (otherwise the closure check has nothing to do). */
export const hasManifests = (steps) => steps.some((step) => (step.copies ?? []).length > 0);

/** True when a step says what it writes: copies, installs, generates, or noManifest with the reason it writes no file. */
export const stepHasManifest = (step) => ['copies', 'installs', 'generates'].some((key) => (step[key] ?? []).length > 0) || typeof step.noManifest === 'string';

/** The positions an order inherits from its base order: every step up to `through`. */
export function basePositions(baseOrder, through) {
  return orderSteps(baseOrder.steps.slice(0, through), `${baseOrder.id}:`).map((position) => ({ ...position, order: `"${baseOrder.title}"` }));
}

/** package names a copied package.json template installs (dependencies and devDependencies; peers are not installs). */
function packageJsonInstalls(file) {
  try {
    const data = JSON.parse(readText(file));
    return [...Object.keys(data.dependencies ?? {}), ...Object.keys(data.devDependencies ?? {})];
  } catch {
    return [];
  }
}

/**
 * The companion list for a package (installed with it): from a dependency policy file
 * ({ packages: { <name>: { companions: [{ package, via }] } } }), given or found as the template with the
 * repo path contracts/dependency-policy.json. Companions pinned through overrides are not installs.
 */
export function companionReader({ policyFile, templates }) {
  let file = policyFile;
  if (!file) for (const map of templates.values()) if (map.has('contracts/dependency-policy.json')) file = map.get('contracts/dependency-policy.json').file;
  if (!file || !existsSync(file)) return () => [];
  let table = {};
  try {
    table = JSON.parse(readText(file)).packages ?? {};
  } catch {
    return () => [];
  }
  return (name) => (table[name]?.companions ?? []).filter((companion) => companion.via !== 'overrides').map((companion) => companion.package);
}

/**
 * Plays an order step by step. A copy event is { path, index, position, skill, file, importsLater }:
 * the first event of a path makes it present from its step on; a swap adds a later event whose own
 * imports are checked from its step. Returns { problems: [{ where, kind, message, fix }], positions,
 * sequence, events } with positions = path -> first event.
 */
export function checkOrder({ title, steps, base = [], templates, companionsOf, config }) {
  const globMatch = makeGlob(config);
  const isGlob = (glob) => /[*?{[]/.test(glob);
  const copyMatches = (entry, path, glob, copy) => (entry.placeholder ? PLACEHOLDER.test(glob) : !PLACEHOLDER.test(glob)) && (!entry.example || copy.examples === true || !isGlob(glob)) && globMatch(path, glob);
  const problems = [];
  const sequence = [...base.map((position) => ({ ...position, inherited: true })), ...orderSteps(steps, `${title}:`).map((position) => ({ ...position, inherited: false }))];
  const firstCopy = new Map();
  const events = [];
  const installedAt = new Map();
  const generated = [];
  const allTemplates = new Map();
  for (const [skill, map] of templates) for (const [path, entry] of map) if (!entry.placeholder) allTemplates.set(path, [...(allTemplates.get(path) ?? []), skill]);

  sequence.forEach((position, index) => {
    const where = `${position.inherited ? `${position.order} ` : ''}${position.label}`;
    for (const copy of position.copies) {
      const map = templates.get(copy.skill);
      if (!map) {
        if (!position.inherited) problems.push({ where, kind: 'manifest', message: `${where} copies from ${copy.skill}, which is not a skill`, fix: 'Name the skill whose templates/ hold the files.' });
        continue;
      }
      if (!position.inherited && !position.skills.includes(copy.skill)) problems.push({ where, kind: 'manifest', message: `${where} copies from ${copy.skill}, which the step does not load`, fix: `Add ${copy.skill} to the step's skills, so its rules and checks apply to the files it brings.` });
      for (const glob of copy.paths) {
        const matched = [...map.keys()].filter((path) => copyMatches(map.get(path), path, glob, copy) && !(copy.exclude ?? []).some((ex) => globMatch(path, ex)));
        if (matched.length === 0 && !position.inherited) problems.push({ where, kind: 'manifest', message: `${where} copies ${glob} from ${copy.skill}, which has no template with that repo path`, fix: `Use the repo path on line 1 of a template in ${copy.skill}'s templates/ or examples/ (a template path that keeps a __PLACEHOLDER__ is copied by a path with the same placeholder), or remove the entry.` });
        for (const path of matched) {
          if (firstCopy.has(path) && !copy.swap && !copy.merge) continue;
          if (copy.merge && !firstCopy.has(path) && !position.inherited) problems.push({ where, kind: 'manifest', message: `${where} merges ${path} from ${copy.skill}, but no earlier step copies that file`, fix: 'Copy the file at this step (drop merge), or merge into a file an earlier step copied.' });
          const event = { path, index, position, skill: copy.skill, file: map.get(path).file, importsLater: copy.importsLater ?? [], deferredTests: copy.deferredTests ?? [], swap: copy.swap === true, merge: copy.merge === true };
          if (!firstCopy.has(path)) firstCopy.set(path, event);
          events.push(event);
          if (path.endsWith('package.json')) for (const name of packageJsonInstalls(event.file)) if (!installedAt.has(name)) installedAt.set(name, index);
        }
      }
    }
    for (const install of position.installs) {
      for (const name of [install.package, ...(install.companions ?? [])]) if (!installedAt.has(name)) installedAt.set(name, index);
      const missing = (companionsOf?.(install.package) ?? []).filter((name) => !(install.companions ?? []).includes(name));
      if (missing.length > 0 && !position.inherited) problems.push({ where, kind: 'manifest', message: `${where} installs ${install.package} without its companion${missing.length > 1 ? 's' : ''} ${missing.join(', ')} (the dependency policy lists ${missing.length > 1 ? 'them' : 'it'})`, fix: `Add ${missing.map((name) => `"${name}"`).join(', ')} to that install's companions.` });
    }
    for (const gen of position.generates) {
      for (const glob of gen.paths) generated.push({ index, glob });
      for (const name of gen.installs ?? []) if (!installedAt.has(name)) installedAt.set(name, index);
    }
  });

  const presentAt = (path, index) => {
    const copied = firstCopy.get(path);
    if (copied && copied.index <= index) return true;
    return generated.some((gen) => gen.index <= index && globMatch(path, gen.glob));
  };
  const resolveAt = (target, index) => presentTarget(target, (candidate) => presentAt(candidate, index));
  const known = (target) => presentTarget(target, (candidate) => firstCopy.has(candidate) || allTemplates.has(candidate) || generated.some((gen) => globMatch(candidate, gen.glob)));
  const importsCache = new Map();
  const importsOfFile = (file) => {
    if (!importsCache.has(file)) importsCache.set(file, importsOf(readText(file), config));
    return importsCache.get(file);
  };

  // 1. Imports: every relative and aliased import is present by the copying step, every npm import installed.
  const own = events.filter((event) => !event.position.inherited && !event.merge).sort((a, b) => a.index - b.index || (a.path < b.path ? -1 : 1));
  for (const event of own) {
    if (!CODE.test(event.path) || event.path.endsWith('.d.ts')) continue;
    const { path, index: at, skill } = event;
    const where = event.position.label;
    const later = (glob, value) => event.importsLater.some((pattern) => globMatch(value, pattern) || pattern === glob);
    for (const specifier of importsOfFile(event.file)) {
      const target = resolveImport(path, specifier, config);
      if (target === null) {
        const name = packageOf(specifier);
        if (name === null) continue;
        const when = installedAt.get(name);
        if (when !== undefined && when <= at) continue;
        if (later(name, name) && when !== undefined) continue;
        const status = when === undefined ? 'no step installs it' : `${sequence[when].label} installs it`;
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) imports the npm package ${name}, which is not installed by then: ${status}`, fix: `Install ${name} (with its companions, from plan-dependency.mjs of dependency-management) in the installs of the step that first copies an importer.` });
        continue;
      }
      if (resolveAt(target, at)) continue;
      const candidate = known(target);
      const first = candidate ? firstCopy.get(candidate) : null;
      if (later(candidate ?? target, candidate ?? target)) {
        if (first || (candidate && generated.some((gen) => globMatch(candidate, gen.glob)))) continue;
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) waits for ${candidate ?? target} (importsLater), which no step of this order copies`, fix: `Copy ${candidate ?? target} at the step that builds it, or drop it from importsLater.` });
      } else if (first && first.index > at) {
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) imports ${candidate}, which ${first.position.label} copies (${first.skill})`, fix: `Copy ${candidate} at ${where} or earlier (with its test), or move ${path} to ${first.position.label}.` });
      } else if (candidate && allTemplates.has(candidate)) {
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) imports ${candidate}, which no step copies (template in ${allTemplates.get(candidate).join(', ')})`, fix: `Add ${candidate} to the copies of ${where} or an earlier step, from its owner skill.` });
      } else if (candidate) {
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) imports ${candidate}, which a later step generates`, fix: `Generate ${candidate} at ${where} or earlier, or move ${path} to the step that generates it.` });
      } else {
        problems.push({ where, kind: 'closure', message: `${path} (${where}, ${skill}) imports ${target}, which no step copies or generates and no skill has a template for`, fix: 'Name the step that writes it (copies or generates), or fix the import.' });
      }
    }
  }

  // 2. Tests travel with their files: a sibling test template is copied in the same step.
  const firsts = [...firstCopy.values()].filter((event) => !event.position.inherited).sort((a, b) => a.index - b.index || (a.path < b.path ? -1 : 1));
  for (const event of firsts) {
    const { path } = event;
    if (!/\.(ts|tsx)$/.test(path) || TEST.test(path) || path.endsWith('.d.ts')) continue;
    const stem = path.replace(/\.(ts|tsx)$/, '');
    const swaps = events.filter((other) => other.path === path && other.swap && other !== event).map((other) => other.index);
    for (const test of [`${stem}.test.ts`, `${stem}.test.tsx`].filter((candidate) => allTemplates.has(candidate) || firstCopy.has(candidate))) {
      const copied = firstCopy.get(test);
      if (copied && copied.index <= event.index) continue;
      if (copied && swaps.includes(copied.index)) continue;
      if (copied && event.deferredTests.some((item) => item.test === test)) continue;
      problems.push({
        where: event.position.label,
        kind: 'closure',
        message: copied ? `${path} (${event.position.label}, ${event.skill}) arrives without its test: ${copied.position.label} copies ${test}` : `${path} (${event.position.label}, ${event.skill}) arrives without its test ${test}, which no step copies (template in ${(allTemplates.get(test) ?? []).join(', ')})`,
        fix: `Copy ${test} in the same step as ${path}; when the test needs a file of a later step (the render helper, the theme), move both to that step, or name it in deferredTests with the reason.`,
      });
    }
  }

  // 3. Coverage: a counted runtime file whose covering tests only arrive at a later step drops
  //    test:coverage between the two steps.
  const counted = (path) => config.coverage.some((glob) => globMatch(path, glob)) && /\.(ts|tsx)$/.test(path) && !TEST.test(path) && !path.endsWith('.d.ts') && !/\/(testing|fixtures)\//.test(path) && !/\/fake-[^/]+$/.test(path);
  const reachCache = new Map();
  const reachedAt = (index) => {
    if (reachCache.has(index)) return reachCache.get(index);
    const seen = new Set();
    const stack = [...firstCopy.values()].filter((event) => event.index <= index && TEST.test(event.path)).map((event) => event.path);
    while (stack.length > 0) {
      const path = stack.pop();
      if (seen.has(path)) continue;
      seen.add(path);
      const event = firstCopy.get(path);
      if (!event || !CODE.test(path)) continue;
      for (const specifier of importsOfFile(event.file)) {
        const target = resolveImport(path, specifier, config);
        if (target === null) continue;
        const hit = resolveAt(target, index);
        if (hit && !seen.has(hit)) stack.push(hit);
      }
    }
    reachCache.set(index, seen);
    return seen;
  };
  const lastIndex = sequence.length - 1;
  for (const event of firsts) {
    const { path } = event;
    if (!counted(path)) continue;
    const source = readText(event.file);
    const head = source.split('\n').slice(0, 6).join('\n');
    if (/\/\/\s*device-only:/.test(head) || /GENERATED by /.test(source.split('\n').slice(0, 3).join('\n'))) continue;
    if (!RUNTIME_EXPORT.test(maskComments(source))) continue;
    if (reachedAt(event.index).has(path) || !reachedAt(lastIndex).has(path)) continue;
    const covering = sequence.findIndex((_, index) => index > event.index && reachedAt(index).has(path));
    problems.push({ where: event.position.label, kind: 'closure', message: `${path} (${event.position.label}, ${event.skill}) has runtime code that only tests of ${sequence[covering].label} reach, so test:coverage drops between the two steps`, fix: `Move ${path} to ${sequence[covering].label} with the test that covers it, or copy that test (and what it needs) at ${event.position.label}.` });
  }
  return { problems, positions: firstCopy, sequence, events };
}
